def captcha_halfway(numbers: Any) -> object {
    total = 0;
    for i in range(int((len(numbers) / 2))) {
        if (numbers[i] == numbers[(i + int((len(numbers) / 2)))]) {
            total += int(numbers[i]);
        }
    }
